import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            Student("2", "Thistle", "Bram", "B", "bram@example.org"),
            Student("1", "Quillon", "Ada", "A", "ada@example.org")
        ])
        self.assertEqual(rows, [
            "Quillon, Ada         A        ada@example.org",
            "Thistle, Bram        B        bram@example.org"
        ])

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([Student("1", "Quillon", "Ada", "A")])
        self.assertIn("Quillon, Ada", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
